let db=null,cloudReady=false,currentUser=null,syncTimer=null; const omniMgmt={compras:[],agenda:[],os:[],contratantes:[],financeiro:[],notificacoes:[],fornecedores:[],atualizacoes:[],projetos:[],crm:[],estoque:[],posvenda:[]};
