const tableFor=k=>k===K.clients?'clientes':k===K.products?'catalogo':k===K.quotes?'propostas':null;
function toRow(k,x){if(k===K.clients)return {nome:x.name||'',endereco:x.address||null,telefone:x.contact||null};if(k===K.products)return {nome:x.name||'',categoria:x.category||null,marca_modelo:x.model||null,descricao:x.description||null,custo:+x.cost||0,preco_venda:+x.sale||0,foto_url:x.photo||null,historico_precos:[...(x.history||[]).filter(h=>!h.__omni),{__omni:true,installCost:+x.installCost||0,installSale:+x.installSale||0,photo:x.photo||''}]};return {cliente_nome:x.client||null,endereco:x.address||null,itens:x.items||[],total:+x.total||0,dados:{number:x.number||'',consultant:x.consultant||'',specifier:x.specifier||'',date:x.date||'',payment:x.payment||'',notes:x.notes||'',deadline:x.deadline||'',warrantySupport:x.warrantySupport||'',summary:x.summary||'',finance:x.finance||{},projectPages:x.projectPages||[],status:x.status||'Em orçamento',approvedAt:x.approvedAt||null}}}
function fromRow(k,x){if(k===K.clients)return {id:x.id,name:x.nome,address:x.endereco||'',contact:x.telefone||''};if(k===K.products)return {id:x.id,name:x.nome,category:x.categoria||'',model:x.marca_modelo||'',description:x.descricao||'',cost:+x.custo||0,sale:+x.preco_venda||0,photo:x.foto_url||'',history:(x.historico_precos||[]).filter(h=>!h.__omni),...((x.historico_precos||[]).find(h=>h.__omni)||{})};let d=x.dados||{};return {id:x.id,client:x.cliente_nome||'',address:x.endereco||'',items:x.itens||[],total:+x.total||0,number:d.number||'',consultant:d.consultant||'',specifier:d.specifier||'',date:d.date||'',payment:d.payment||'',notes:d.notes||'',deadline:d.deadline||'',warrantySupport:d.warrantySupport||'',summary:d.summary||'',finance:d.finance||{},projectPages:d.projectPages||[],status:d.status||'Em orçamento',approvedAt:d.approvedAt||null}}
async function pullCloud(){for(const k of [K.clients,K.products,K.quotes]){let t=tableFor(k),r=await db.from(t).select('*').order('id');if(r.error)throw r.error;localStorage.setItem(k,JSON.stringify((r.data||[]).map(x=>fromRow(k,x))))}}
async function omniReload(k){let t=tableFor(k),r=await db.from(t).select('*').order('id');if(r.error)throw r.error;let v=(r.data||[]).map(x=>fromRow(k,x));localStorage.setItem(k,JSON.stringify(v));return v}
