async function go(v){view=v;if(['compras','agenda','os','contractors','financeHealth','updates','operations','projects','crm','stock','afterSales'].includes(v))await omniRefreshManagement();render()} function stat(n,l,target=''){return '<div class="stat"'+(target?' role="button" tabindex="0" onclick="go(\''+target+'\')" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();go(\''+target+'\')}" style="cursor:pointer"':'')+'><strong>'+n+'</strong><span>'+l+'</span>'+(target?'<small style="display:block;margin-top:6px">Ver detalhes ›</small>':'')+'</div>'}
function home(){let q=get(K.quotes),p=get(K.products),c=get(K.clients),sum=q.reduce((a,x)=>a+(+x.total||0),0);return '<section class="hero"><span class="eyebrow">PAINEL DE CONTROLE</span><h1>Boa gestão começa<br>com uma boa proposta.</h1><p>Crie e organize os orçamentos da OmniSpectra em um só lugar.</p><button class="primary" onclick="go(\'quote\')">＋ Criar nova proposta</button></section><div class="stats">'+stat(c.length,'Clientes')+stat(p.length,'Itens no catálogo')+stat(q.length,'Propostas')+stat(br(sum),'Valor orçado')+'</div><div class="sectionTitle"><h2>Propostas recentes</h2><button class="link" onclick="go(\'quotes\')">Ver todas</button></div>'+quoteCards(q.slice(-4).reverse())}
