 if(/videoporteiro|v[ií]deo porteiro|interfone|xpe/.test(n)){add('Passagem de cabeamento de vídeo porteiro / interfonia','Serviço',120);let p=get(K.products).find(y=>+y.sale>0&&((y.name||'').toLowerCase().includes('f-utp blindado')||(y.model||'').toLowerCase().includes('landutti f-utp')));if(p)a.push({...p,qty:25*qty,__auto:true});else add('Cabo F-UTP blindado Cat5e','Insumo',14.73,25*qty,'Valor por metro');return a}
