function omniAgendaForm(){form.innerHTML='<div class="panel"><h3>Novo agendamento</h3><div class="two"><div class="field"><label>Técnico</label><select id="agTech"><option>Fernando</option><option>Leonardo</option></select></div><div class="field"><label>Data</label><input id="agDate" type="date"></div></div><div class="two"><div class="field"><label>Período</label><select id="agPeriod"><option>Manhã</option><option>Tarde</option><option>Dia inteiro</option></select></div><div class="field"><label>Tipo</label><select id="agType"><option>Serviço</option><option>Orçamento</option><option>Compromisso pessoal</option></select></div></div><div class="field"><label>Título / cliente</label><input id="agTitle"></div><div class="field"><label>Endereço</label><input id="agAddress"></div><div class="field"><label>Contratante (opcional)</label><input id="agContractor"></div><button class="primary full" onclick="omniSaveAgenda()">Salvar agendamento</button></div>'}
async function omniSaveAgenda(){if(!agDate.value||!agTitle.value)return alert('Informe data e título.');const existing=omniMgmt.agenda.filter(x=>x.tecnico===agTech.value&&x.data===agDate.value&&x.status!=='Cancelado');const clash=existing.some(x=>x.periodo==='Dia inteiro'||agPeriod.value==='Dia inteiro'||x.periodo===agPeriod.value);if(clash)return alert('Este período já está ocupado para '+agTech.value+'.');let period=agPeriod.value;if((agAddress.value||'').toLowerCase().includes('são paulo'))period='Dia inteiro';const {data,error}=await db.from('agenda').insert({tecnico:agTech.value,data:agDate.value,periodo:period,tipo:agType.value,titulo:agTitle.value,cliente_final:agTitle.value,endereco:agAddress.value,contratante_nome:agContractor.value,status:'Agendado'}).select().single();if(error)return alert(error.message);if(agType.value==='Serviço'){const n='OS-'+String(Date.now()).slice(-6);await db.from('ordens_servico').insert({agenda_id:data.id,numero:n,tecnico:agTech.value,contratante_nome:agContractor.value,cliente_final:agTitle.value,endereco:agAddress.value,data:agDate.value,periodo:period,status:'Aberta'});}await db.from('notificacoes').insert({tipo:'Agenda',titulo:'Novo agendamento para '+agTech.value,mensagem:new Date(agDate.value+'T12:00:00').toLocaleDateString('pt-BR')+' · '+period+' · '+agTitle.value});await omniRefreshManagement();render()}
function osView(){let a=omniMgmt.os;return pageHead('Ordens de Serviço','Registre execução, pendências, materiais extras e finalize o atendimento.','Atualizar','go(\'os\')')+(a.length?a.map(x=>'<article class="proposal"><div><span class="category">'+esc(x.numero||'OS')+' · '+esc(x.status)+'</span><h3>'+esc(x.cliente_final||'Cliente')+'</h3><small>'+esc(x.tecnico||'')+' · '+(x.data?new Date(x.data+'T12:00:00').toLocaleDateString('pt-BR'):'')+' · '+esc(x.periodo||'')+'</small></div><div class="proposalActions"><strong>'+br((+x.valor_servico||0)+(+x.valor_materiais||0)+(+x.taxa_cancelamento||0))+'</strong><button class="editbtn" onclick="omniOSForm('+x.id+')">Abrir OS</button></div></article>').join(''):empty('Nenhuma OS criada. Serviços lançados na agenda podem gerar OS automaticamente.'))+'<div id="form"></div>'}
function omniOSForm(id){const x=omniMgmt.os.find(y=>y.id===id);if(!x)return;form.innerHTML='<div class="panel"><h3>'+esc(x.numero||'OS')+' · '+esc(x.cliente_final||'')+'</h3><div class="field"><label>Serviço realizado</label><textarea id="osDone">'+esc(x.realizado||'')+'</textarea></div><div class="field"><label>Pendências / o que falta</label><textarea id="osPending">'+esc(x.pendencias||'')+'</textarea></div><div class="two"><div class="field"><label>Valor do serviço</label><input id="osService" type="number" step=".01" value="'+(+x.valor_servico||0)+'"></div><div class="field"><label>Materiais extras utilizados (R$)</label><input id="osMaterials" type="number" step=".01" value="'+(+x.valor_materiais||0)+'"></div></div><div class="field"><label>Descrição dos materiais utilizados</label><textarea id="osMatDesc">'+esc((x.materiais&&x.materiais[0]&&x.materiais[0].descricao)||'')+'</textarea></div><button class="primary" onclick="omniFinishOS('+id+')">Finalizar OS</button><button class="ghost" style="margin-left:8px" onclick="omniSaveOS('+id+')">Salvar</button></div>';form.scrollIntoView({behavior:'smooth'})}
async function omniSaveOS(id,finish=false){const patch={realizado:osDone.value,pendencias:osPending.value,valor_servico:+osService.value||0,valor_materiais:+osMaterials.value||0,materiais:osMatDesc.value?[{descricao:osMatDesc.value,valor:+osMaterials.value||0}]:[],atualizado_em:new Date().toISOString()};if(finish){patch.status='Finalizada';patch.finalizada_em=new Date().toISOString()}const {error}=await db.from('ordens_servico').update(patch).eq('id',id);if(error)return alert(error.message);if(finish){const x=omniMgmt.os.find(y=>y.id===id);const total=patch.valor_servico+patch.valor_materiais+(+x.taxa_cancelamento||0);if(total>0)await db.from('movimentos_financeiros').insert({tipo:'Entrada',categoria:'Serviços de terceiros',descricao:(x.contratante_nome||'Contratante')+' · '+(x.numero||'OS'),valor:total,data_prevista:new Date().toISOString().slice(0,10),status:'A receber',referencia_tipo:'OS',referencia_id:id});}await omniRefreshManagement();render()}
async function omniFinishOS(id){await omniSaveOS(id,true)}
function contractorsView(){let a=omniMgmt.contratantes;return pageHead('Contratantes','Cadastre valores, PIX e regras de cancelamento por empresa.','＋ Novo contratante','omniContractorForm()')+'<div id="form"></div>'+(a.length?a.map(x=>'<article class="listcard"><div class="grow"><b>'+esc(x.nome)+'</b><small>Meio período '+br(x.valor_meio_periodo)+' · diária '+br(x.valor_diaria)+' · cancelamento 48h '+br(x.taxa_cancelamento_48h)+' / 24h '+br(x.taxa_cancelamento_24h)+'</small></div><span class="statusPill">'+esc(x.modo_agendamento)+'</span></article>').join(''):empty('Cadastre Quadre, Dexter e futuros contratantes.'))}
