async function omniSaveContractor(){if(!coName.value)return alert('Informe a empresa.');const {error}=await db.from('contratantes').insert({nome:coName.value,email:coEmail.value,pix:coPix.value,valor_meio_periodo:+coHalf.value||0,valor_diaria:+coDay.value||0,taxa_cancelamento_48h:+co48.value||30,taxa_cancelamento_24h:+co24.value||50,modo_agendamento:coMode.value});if(error)return alert(error.message);await omniRefreshManagement();render()}
function financeHealth(){const m=omniMgmt.financeiro,compras=omniMgmt.compras;const entradas=m.filter(x=>x.tipo==='Entrada'&&x.status!=='Recebido').reduce((a,x)=>a+(+x.valor||0),0),recebido=m.filter(x=>x.tipo==='Entrada'&&x.status==='Recebido').reduce((a,x)=>a+(+x.valor||0),0),saidas=m.filter(x=>x.tipo==='Saída'&&x.status!=='Pago').reduce((a,x)=>a+(+x.valor||0),0),comp= compras.filter(x=>x.status==='A comprar').reduce((a,x)=>a+(+x.custo_unitario||0)*(+x.quantidade||0),0);const caixa=+(localStorage.getItem('omni_cash_base')||0),projected=caixa+entradas-saidas-comp;const state=projected<0?['Crítico','bad']:projected<Math.max(1000,caixa*.2)?['Atenção','warn']:['Saudável','ok'];return '<div class="pagehead"><span class="eyebrow">FINANCEIRO</span><h1>Saúde da Empresa</h1><p>Projeção gerencial. Não representa o saldo bancário real.</p></div><div class="panel"><div class="field"><label>Caixa informado manualmente</label><input type="number" step=".01" value="'+caixa+'" onchange="localStorage.setItem(\'omni_cash_base\',this.value);render()"></div></div><div class="stats">'+stat(br(caixa),'Caixa informado')+stat(br(entradas),'A receber')+stat(br(comp+saidas),'Compromissos')+stat(br(projected),'Caixa projetado')+'</div><div class="health '+state[1]+'"><b>'+state[0]+'</b><span>Projeção após recebimentos e compromissos registrados.</span></div>'+((projected<0)?'<div class="panel"><h3>Atenção ao capital de giro</h3><p>Faltariam aproximadamente <b>'+br(Math.abs(projected))+'</b> para cobrir os compromissos registrados. Considere reforçar a entrada dos próximos projetos antes de antecipar compras.</p></div>':'')+'<div class="sectionTitle"><h2>Movimentos previstos</h2><button class="link" onclick="omniFinanceForm()">＋ Lançar</button></div><div id="form"></div>'+(m.map(x=>'<article class="listcard"><div class="grow"><span class="category">'+esc(x.tipo)+' · '+esc(x.status)+'</span><b>'+esc(x.descricao)+'</b><small>'+esc(x.categoria)+' · '+(x.data_prevista?new Date(x.data_prevista+'T12:00:00').toLocaleDateString('pt-BR'):'')+'</small></div><strong>'+br(x.valor)+'</strong></article>').join('')||empty('Sem movimentos financeiros.'))}
function omniFinanceForm(){form.innerHTML='<div class="panel"><div class="two"><div class="field"><label>Tipo</label><select id="fiType"><option>Entrada</option><option>Saída</option></select></div><div class="field"><label>Data prevista</label><input id="fiDate" type="date"></div></div><div class="field"><label>Descrição</label><input id="fiDesc"></div><div class="field"><label>Categoria</label><input id="fiCat" placeholder="Insumos, impostos, serviço..."></div><div class="field"><label>Valor</label><input id="fiValue" type="number" step=".01"></div><button class="primary full" onclick="omniSaveFinance()">Salvar lançamento</button></div>'}
