function updatesView(){let a=omniMgmt.atualizacoes,n=omniMgmt.notificacoes.filter(x=>!x.lida);return '<div class="pagehead"><span class="eyebrow">CATÁLOGOS E AVISOS</span><h1>Atualizações</h1><p>Alterações de fornecedores ficam aguardando aprovação antes de afetar o catálogo oficial.</p></div><div class="stats">'+stat(n.length,'Avisos não lidos')+stat(a.filter(x=>x.status==='Aguardando aprovação').length,'Aguardando aprovação')+stat(a.filter(x=>x.tipo_alteracao==='Novo produto').length,'Produtos novos')+stat(a.filter(x=>x.tipo_alteracao==='Preço alterado').length,'Preços alterados')+'</div>'+(a.length?a.map(x=>'<article class="listcard"><div class="grow"><span class="category">'+esc(x.fornecedor_nome||'Fornecedor')+' · '+esc(x.tipo_alteracao)+'</span><b>'+esc(x.produto_nome)+'</b><small>'+(x.custo_anterior!=null?br(x.custo_anterior)+' → '+br(x.custo_novo):'Novo item')+' · '+esc(x.status)+'</small></div></article>').join(''):empty('Nenhuma atualização de fornecedor pendente.'))+'<div class="panel"><h3>Portal do fornecedor</h3><p>A estrutura de revisão já está preparada. O acesso externo será liberado somente com permissões isoladas, para que fornecedores nunca tenham acesso aos dados internos ou alterem o catálogo oficial diretamente.</p></div>'}

function projectsView(){let a=omniMgmt.projetos;return pageHead('Projetos / Obras','O centro da operação: comercial, compras, execução e rentabilidade.','＋ Novo projeto','omniProjectForm()')+'<div id="form"></div>'+(a.length?a.map(x=>{let cost=(+x.custo_equipamentos||0)+(+x.custo_insumos||0)+(+x.custo_mao_obra||0)+(+x.custo_fretes||0)+(+x.outros_custos||0),res=(+x.valor_venda||0)-cost,mar=(+x.valor_venda?res/(+x.valor_venda)*100:0);return '<article class="proposal"><div><span class="category">'+esc(x.status)+'</span><h3>'+esc(x.nome)+'</h3><small>'+esc(x.cliente_nome||'')+' · '+esc(x.endereco||'')+'</small></div><div class="proposalActions"><strong>'+br(res)+' resultado</strong><span class="statusPill">'+mar.toFixed(1)+'% margem</span></div></article>'}).join(''):empty('Nenhum projeto criado ainda.'))}
