function afterSalesView(){let a=omniMgmt.posvenda;return pageHead('Pós-venda e Garantias','Histórico de entrega, garantia e assistência dos projetos.','Atualizar','go(\'afterSales\')')+(a.length?a.map(x=>'<article class="listcard"><div class="grow"><span class="category">'+esc(x.status)+'</span><b>'+esc(x.cliente_nome||'Projeto')+'</b><small>Entrega '+(x.data_entrega?new Date(x.data_entrega+'T12:00:00').toLocaleDateString('pt-BR'):'—')+' · Garantia até '+(x.garantia_ate?new Date(x.garantia_ate+'T12:00:00').toLocaleDateString('pt-BR'):'—')+'</small></div></article>').join(''):empty('Nenhum projeto em pós-venda.'))}
function omniDashboard(){let q=get(K.quotes),today=new Date().toISOString().slice(0,10),openOS=omniMgmt.os.filter(x=>x.status!=='Finalizada'&&x.status!=='Cancelada').length,buy=omniMgmt.compras.filter(x=>x.status==='A comprar').reduce((a,x)=>a+(+x.custo_unitario||0)*(+x.quantidade||0),0),recv=omniMgmt.financeiro.filter(x=>x.tipo==='Entrada'&&x.status!=='Recebido').reduce((a,x)=>a+(+x.valor||0),0),todayJobs=omniMgmt.agenda.filter(x=>x.data===today&&x.status!=='Cancelado').length,next=omniMgmt.crm.filter(x=>x.data_proxima_acao&&x.data_proxima_acao<=today&&x.etapa!=='Perdido'&&x.etapa!=='Aprovado').length;let aging=q.map((x,i)=>{let p=(x.date||'').split('/'),d=p.length===3?new Date(+p[2],+p[1]-1,+p[0]):new Date(x.approvedAt||Date.now()),days=Math.max(0,Math.floor((Date.now()-d.getTime())/86400000));return {x,i,days}}).filter(o=>o.x.status!=='Aprovado'&&o.days>=10).sort((a,b)=>b.days-a.days);return '<section class="hero"><span class="eyebrow">PAINEL EXECUTIVO</span><h1>OmniSpectra em um olhar.</h1><p>Comercial, operação e financeiro conectados.</p><button class="primary" onclick="go(\'quote\')">＋ Primeiro / novo orçamento</button></section><div class="stats">'+stat(todayJobs,'Atendimentos hoje','agenda')+stat(br(recv),'A receber','financeHealth')+stat(br(buy),'Compras pendentes','compras')+stat(openOS,'OS abertas','os')+'</div><div class="stats">'+stat(q.filter(x=>x.status!=='Aprovado').length,'Propostas abertas','quotes')+stat(next,'Follow-ups vencidos','crm')+stat(omniMgmt.projetos.filter(x=>x.status!=='Concluído').length,'Projetos ativos','projects')+stat(omniMgmt.estoque.filter(x=>+x.quantidade<=+x.estoque_minimo).length,'Itens para repor','stock')+'</div><div class="panel"><h3>Acompanhamento de propostas</h3>'+(aging.length?aging.slice(0,6).map(o=>'<article class="listcard"><div class="grow"><span class="category">ATENÇÃO · '+o.days+' DIAS</span><b>'+esc(o.x.number||'Proposta')+' · '+esc(o.x.client||'Cliente')+'</b><small>'+br(o.x.total)+' · sem aprovação registrada</small></div><button class="editbtn" onclick="editQuote('+o.i+')">Abrir</button></article>').join(''):'<small class="hint">Nenhuma proposta parada há 10 dias ou mais.</small>')+'</div><div class="panel"><h3>Preparação para uso real</h3><div class="launchChecklist"><label class="check"><input type="checkbox" checked disabled> Dashboard e módulos-base estruturados</label><label class="check"><input type="checkbox" checked disabled> Segurança interna do banco reforçada</label><label class="check"><input type="checkbox" disabled> Sincronização de clientes, catálogo e propostas por registro/ID</label><label class="check"><input type="checkbox" disabled> Backup e recuperação testados</label><label class="check"><input type="checkbox" disabled> Numeração automática de propostas validada</label><label class="check"><input type="checkbox" disabled> Teste simultâneo Fernando + Leonardo</label><label class="check"><input type="checkbox" disabled> Perfis e permissões por função (incluindo Projetos/Natália)</label><label class="check"><input type="checkbox" disabled> Validação do fluxo financeiro com responsável da área</label><label class="check"><input type="checkbox" disabled> Portal de contratantes e fornecedores — fase futura</label></div></div><div class="moduleGrid"><button class="moduleCard" onclick="go(\'projects\')"><b>Projetos / Obras</b><small>Rentabilidade e andamento centralizados</small></button><button class="moduleCard" onclick="go(\'crm\')"><b>CRM</b><small>Oportunidades e próximos contatos</small></button><button class="moduleCard" onclick="go(\'stock\')"><b>Estoque</b><small>Saldo próprio e reposição</small></button><button class="moduleCard" onclick="go(\'afterSales\')"><b>Pós-venda</b><small>Garantias e assistência</small></button></div>'}
function render(){if(!currentUser)return authScreen();let c=view==='home'?omniDashboard():view==='clients'?clients():view==='products'?products():view==='quote'?quote():view==='quotes'?quotes():view==='commercial'?commercial():view==='projects'?projectsView():view==='crm'?crmView():view==='stock'?stockView():view==='afterSales'?afterSalesView():view==='operations'?operations():view==='compras'?comprasView():view==='agenda'?agendaView():view==='os'?osView():view==='contractors'?contractorsView():view==='financeHealth'?financeHealth():view==='updates'?updatesView():view==='proposalEditor'?proposalEditor():view==='visual'?omniVisualEditor():home();shell(c);if(view==='quote'){renderSelected();renderFinance()}if(view==='proposalEditor'){updateOmniPPTStatus();updateOmniPDFTemplateStatus()}}
(async()=>{try{app.innerHTML='<main class="wrap"><div class="panel"><h2>Conectando à OmniSpectra…</h2><p>Aguarde enquanto carregamos seus dados.</p></div></main>';let ctl=new AbortController(),timer=setTimeout(()=>ctl.abort(),12000),response;try{response=await fetch('https://poxxqtwolfupfobfhuyd.supabase.co/functions/v1/public-config',{cache:'no-store',signal:ctl.signal})}finally{clearTimeout(timer)}if(!response.ok)throw Error('Configuração indisponível (HTTP '+response.status+')');let cfg=await response.json();if(!cfg.url||!cfg.key)throw new Error('Configuração pública incompleta');if(!window.supabase||!window.supabase.createClient)throw new Error('Biblioteca Supabase não carregou');db=window.supabase.createClient(cfg.url,cfg.key);let {data,error}=await Promise.race([db.auth.getSession(),new Promise((_,reject)=>setTimeout(()=>reject(Error('Tempo excedido na autenticação')),12000))]);if(error)throw error;if(data.session)await startSession(data.session.user);else authScreen();initializeBlankPDF().catch(e=>console.warn('PDF initialization:',e))}catch(e){console.error(e);app.innerHTML='<main class="wrap"><div class="panel"><h2>Não foi possível abrir a OmniSpectra</h2><p>'+esc(e.message||'Erro desconhecido')+'</p><button class="primary" onclick="location.reload()">Tentar novamente</button></div></main>'}})();